'''Проверка initData из Telegram Mini App.

Telegram подписывает строку initData так:
secret = HMAC-SHA256(key='WebAppData', msg=токен бота)
подпись = HMAC-SHA256(key=secret, msg=строка 'ключ=значение' без поля hash,
        отсортированная по ключам и соединённая переводом строки).

Подпись сверяется для каждого известного токену проекта: Mini App может быть открыт
и из основного, и из ученического бота.
'''
from __future__ import annotations

import hashlib
import hmac
import json
import time
from dataclasses import dataclass
from typing import Iterable
from urllib.parse import parse_qsl


@dataclass(frozen=True)
class WebAppUser:
    tg_id: int
    first_name: str
    username: str | None


class InitDataError(Exception):
    '''initData не прошла проверку. Текст безопасен для ответа клиенту.'''


def _signature(check_string: str, token: str) -> str:
    secret = hmac.new(b'WebAppData', token.encode('utf-8'), hashlib.sha256).digest()
    return hmac.new(secret, check_string.encode('utf-8'), hashlib.sha256).hexdigest()


def verify_init_data(init_data: str, tokens: Iterable[str], max_age: int,
                     now: float | None = None) -> WebAppUser:
    '''Возвращает проверенного пользователя или поднимает InitDataError.'''
    if not init_data:
        raise InitDataError('нет данных авторизации: откройте приложение из Telegram')

    data = dict(parse_qsl(init_data, keep_blank_values=True))
    received = str(data.pop('hash', '')).lower()
    if not received:
        raise InitDataError('в данных авторизации нет подписи')

    check_string = '\n'.join(f'{key}={value}' for key, value in sorted(data.items()))
    # compare_digest защищает от подбора подписи по времени ответа
    if not any(hmac.compare_digest(_signature(check_string, token), received)
               for token in tokens if token):
        raise InitDataError('подпись данных не совпала')

    try:
        auth_date = int(data.get('auth_date', ''))
    except ValueError:
        raise InitDataError('некорректная дата авторизации') from None
    current = time.time() if now is None else now
    if current - auth_date > max_age:
        raise InitDataError('сессия истекла: закройте приложение и откройте его заново')
    if auth_date > current + 60:
        raise InitDataError('дата авторизации указана в будущем')

    try:
        user = json.loads(data.get('user', ''))
    except json.JSONDecodeError:
        raise InitDataError('некорректные данные пользователя') from None
    if not isinstance(user, dict) or not isinstance(user.get('id'), int):
        raise InitDataError('некорректные данные пользователя')

    return WebAppUser(
        tg_id=user['id'],
        first_name=str(user.get('first_name') or ''),
        username=user.get('username'),
    )

'''Общие функции API: единый формат ошибок, чтение JSON, проверка администратора, маскировка.'''
from __future__ import annotations

import functools

from aiohttp import web

from core.config import config
from services.webapp_flow import FlowError


def flow_handler(func):
    '''Превращает FlowError в JSON-ответ {'error': текст} с нужным HTTP-кодом.'''

    @functools.wraps(func)
    async def wrapper(request: web.Request) -> web.StreamResponse:
        try:
            return await func(request)
        except FlowError as exc:
            return web.json_response({'error': str(exc)}, status=exc.status)

    return wrapper


async def read_json(request: web.Request) -> dict:
    try:
        body = await request.json()
    except ValueError:
        raise FlowError('Некорректный JSON в запросе.') from None
    if not isinstance(body, dict):
        raise FlowError('Ожидался JSON-объект.')
    return body


def require_admin(request: web.Request) -> None:
    '''Доступ только по ADMIN_IDS. tg_id берётся из проверенного initData.'''
    if request['user'].tg_id not in config.ADMIN_IDS:
        raise FlowError('Нет доступа.', status=403)


def int_query(request: web.Request, name: str, default: int = 0) -> int:
    raw = request.query.get(name, '')
    return int(raw) if raw.isdigit() else default


def mask_secret(value: str | None) -> str | None:
    '''Ключ наружу отдаётся только маской: полный ключ во фронтенд не попадает.'''
    if not value:
        return None
    return '***' + value[-4:] if len(value) > 8 else '***'

'''API ученика. Все маршруты требуют действительного initData.'''
from __future__ import annotations

from aiohttp import web

from api.common import flow_handler, int_query, read_json
from services import webapp_flow as flow


@flow_handler
async def state_view(request: web.Request) -> web.Response:
    return web.json_response(await flow.get_state(request['user'].tg_id))


@flow_handler
async def register_view(request: web.Request) -> web.Response:
    user = request['user']
    body = await read_json(request)
    await flow.register(request.app['bot'], user.tg_id, user.username, body.get('full_name'))
    return web.json_response(await flow.get_state(user.tg_id))


@flow_handler
async def start_view(request: web.Request) -> web.Response:
    user = request['user']
    notice = await flow.start_dialog(request.app['bot'], user.tg_id)
    return web.json_response({'notice': notice, 'state': await flow.get_state(user.tg_id)})


@flow_handler
async def finish_view(request: web.Request) -> web.Response:
    result = await flow.finish_dialog(request.app['bot'], request['user'].tg_id)
    return web.json_response(result)


@flow_handler
async def message_view(request: web.Request) -> web.Response:
    user = request['user']
    body = await read_json(request)
    result = await flow.handle_message(request.app['bot'], user.tg_id, body.get('text'))
    return web.json_response(result)


@flow_handler
async def chat_view(request: web.Request) -> web.Response:
    return web.json_response(await flow.get_chat(request['user'].tg_id))


@flow_handler
async def dialogs_view(request: web.Request) -> web.Response:
    page = int_query(request, 'page', 0)
    return web.json_response(await flow.list_dialogs(request['user'].tg_id, page))


@flow_handler
async def dialog_view(request: web.Request) -> web.Response:
    session_id = int(request.match_info['session_id'])
    return web.json_response(await flow.dialog_detail(request['user'].tg_id, session_id))


def setup(router: web.UrlDispatcher) -> None:
    router.add_get('/api/student/state', state_view)
    router.add_post('/api/student/register', register_view)
    router.add_post('/api/student/dialog', start_view)
    router.add_post('/api/student/dialog/finish', finish_view)
    router.add_post('/api/student/message', message_view)
    router.add_get('/api/student/chat', chat_view)
    router.add_get('/api/student/dialogs', dialogs_view)
    router.add_get(r'/api/student/dialogs/{session_id:\d+}', dialog_view)

import asyncio
import copy
import json
import logging
from dataclasses import dataclass
from pathlib import Path

from aiogram import Bot, Dispatcher

from core.bot_status import (
    STATE_ERROR,
    STATE_RUNNING,
    STATE_STARTING,
    STATE_STOPPED,
    make_session,
    set_status,
)
from core.config import config
from core.plugin_loader import Plugin, build_router
from services.crypto import SecretDecryptError, decrypt_value, encrypt_value

logger = logging.getLogger(__name__)

ROOT = Path(__file__).resolve().parent.parent
BOTS_FILE = ROOT / 'configs' / 'bots.json'


@dataclass(frozen=True)
class BotSpec:
    name: str
    token: str
    role: str  # 'main', 'helper' или 'student'


def read_bots_data() -> dict:
    '''Возвращает содержимое bots.json с расшифрованными токенами.

    Битый файл и нерасшифрованный токен вызывают ValueError, чтобы файл не перезаписывался.
    '''
    if not BOTS_FILE.exists():
        return {'helpers': []}
    raw = BOTS_FILE.read_text(encoding='utf-8-sig').strip()
    if not raw:
        return {'helpers': []}
    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ValueError(f'configs/bots.json повреждён: {exc}') from exc
    if not isinstance(data, dict) or not isinstance(data.get('helpers', []), list):
        raise ValueError('configs/bots.json: поле "helpers" должно быть списком')
    data.setdefault('helpers', [])
    for item in data['helpers']:
        if isinstance(item, dict) and isinstance(item.get('token'), str):
            try:
                item['token'] = decrypt_value(item['token'])
            except SecretDecryptError as exc:
                raise ValueError(
                    f'configs/bots.json: токен бота «{item.get("name", "?")}» не расшифрован ({exc}). '
                    'Доп. боты не запущены. Исправьте SETTINGS_KEY или удалите запись и добавьте бота заново'
                ) from exc
    return data


def write_bots_data(data: dict) -> None:
    '''Атомарная запись: сбой не оставит битый JSON. Токены пишутся зашифрованными.'''
    payload = copy.deepcopy(data)
    for item in payload.get('helpers', []):
        if isinstance(item, dict) and isinstance(item.get('token'), str) and item['token']:
            item['token'] = encrypt_value(item['token'])
    BOTS_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = BOTS_FILE.with_name(BOTS_FILE.name + '.tmp')
    tmp.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
    tmp.replace(BOTS_FILE)


def migrate_bots_file() -> None:
    '''Однократно шифрует открытые токены, например добавленные установщиком.'''
    if not BOTS_FILE.exists():
        return
    try:
        data = read_bots_data()
    except ValueError as exc:
        logger.error('%s. Миграция токенов пропущена', exc)
        return
    write_bots_data(data)


def read_extra_bots() -> list[BotSpec]:
    '''Включённые доп. боты. Ошибка файла не останавливает главного бота.'''
    try:
        data = read_bots_data()
    except ValueError as exc:
        logger.error('%s', exc)
        return []

    specs: list[BotSpec] = []
    for item in data['helpers']:
        if not isinstance(item, dict) or not item.get('enabled', True):
            continue
        token = item.get('token')
        if not isinstance(token, str) or not token.strip():
            logger.warning('Запись без токена в bots.json пропущена: %r', item.get('name'))
            continue
        specs.append(BotSpec(name=str(item.get('name', 'helper')), token=token.strip(), role='helper'))
    return specs


def known_tokens() -> set[str]:
    '''Все токены проекта, включая выключенные доп. боты.'''
    tokens = {config.BOT_TOKEN}
    if config.STUDENT_BOT_TOKEN:
        tokens.add(config.STUDENT_BOT_TOKEN.strip())
    try:
        data = read_bots_data()
    except ValueError:
        return tokens
    for item in data['helpers']:
        if isinstance(item, dict) and item.get('token'):
            tokens.add(str(item['token']).strip())
    return tokens


def add_extra_bot(name_hint: str, token: str) -> str:
    '''Добавляет бота в bots.json и возвращает уникальное имя. Запуск — после перезапуска.'''
    data = read_bots_data()
    taken = {item.get('name') for item in data['helpers'] if isinstance(item, dict)}
    base = name_hint or 'helper'
    name, counter = base, 2
    while name in taken:
        name = f'{base}_{counter}'
        counter += 1
    data['helpers'].append({'name': name, 'token': token, 'enabled': True})
    write_bots_data(data)
    return name


def build_specs() -> list[BotSpec]:
    '''Главный бот всегда первый: от него зависит создание топика преподавателя.
    Один токен не запускается дважды. Пропущенный дубль получает статус с причиной,
    чтобы в экране «Боты» не выглядел как ещё не запущенный.
    '''
    specs = [BotSpec(name='main', token=config.BOT_TOKEN, role='main')]

    student_token = (config.STUDENT_BOT_TOKEN or '').strip()
    if student_token:
        specs.append(BotSpec(name='student', token=student_token, role='student'))

    owners = {spec.token: spec.name for spec in specs}
    for spec in read_extra_bots():
        if spec.token in owners:
            owner = owners[spec.token]
            logger.warning('Доп. бот %s использует уже занятый токен и пропущен', spec.name)
            set_status(
                spec.name, spec.role, STATE_STOPPED,
                error=f'токен уже используется ботом «{owner}». '
                      'Удалите запись из configs/bots.json',
            )
            continue
        owners[spec.token] = spec.name
        specs.append(spec)
    return specs


def create_bot(spec: BotSpec, plugins: list[Plugin]) -> tuple[Bot, Dispatcher]:
    bot = Bot(token=spec.token, session=make_session())
    dp = Dispatcher()
    dp.workflow_data.update(bot_role=spec.role, bot_name=spec.name)
    for plugin in plugins:
        if spec.role in plugin.roles:
            dp.include_router(build_router(plugin))
    return bot, dp


async def run_bot(spec: BotSpec, bot: Bot, dp: Dispatcher) -> None:
    '''Ошибка вспомогательного бота не останавливает главного.'''
    set_status(spec.name, spec.role, STATE_STARTING)
    try:
        await bot.delete_webhook(drop_pending_updates=True)
        me = await bot.get_me()
        set_status(spec.name, spec.role, STATE_RUNNING, username=me.username)
        logger.info('Бот @%s (%s) запущен', me.username, spec.role)
        await dp.start_polling(bot, handle_signals=False)
        set_status(spec.name, spec.role, STATE_STOPPED)
    except asyncio.CancelledError:
        set_status(spec.name, spec.role, STATE_STOPPED)
        raise
    except Exception as exc:
        masked = str(exc).replace(spec.token, '***')
        set_status(spec.name, spec.role, STATE_ERROR,
                   error=f'{type(exc).__name__}: {masked[:150]}')
        # Traceback только при DEBUG: он может содержать фрагменты запросов с токеном
        logger.error('Бот %s остановлен с ошибкой %s: %s', spec.name, type(exc).__name__, masked,
                     exc_info=logger.isEnabledFor(logging.DEBUG))
        if spec.role == 'main':
            raise

import logging
from dataclasses import dataclass, field
from datetime import datetime

from aiogram import Bot
from aiogram.client.session.aiohttp import AiohttpSession
from aiogram.exceptions import TelegramAPIError, TelegramUnauthorizedError

from core.config import config

logger = logging.getLogger(__name__)

PROXY_URL = 'http://127.0.0.1:12334'

STATE_STARTING = 'starting'
STATE_RUNNING = 'running'
STATE_STOPPED = 'stopped'
STATE_ERROR = 'error'

MEMBER_STATUSES = {'creator', 'administrator', 'member', 'restricted'}
ADMIN_STATUSES = {'creator', 'administrator'}


@dataclass(frozen=True)
class BotStatus:
    name: str
    role: str
    state: str
    username: str | None = None
    error: str | None = None
    updated_at: datetime = field(default_factory=datetime.now)


_registry: dict[str, BotStatus] = {}


def set_status(name: str, role: str, state: str,
               username: str | None = None, error: str | None = None) -> None:
    previous = _registry.get(name)
    if username is None and previous is not None:
        username = previous.username
    _registry[name] = BotStatus(name=name, role=role, state=state,
                                username=username, error=error)


def get_status(name: str) -> BotStatus | None:
    return _registry.get(name)


def make_session() -> AiohttpSession:
    return AiohttpSession(proxy=PROXY_URL)


@dataclass(frozen=True)
class TokenProbe:
    status: str  # 'ok' | 'invalid' | 'unknown'
    user_id: int | None = None
    username: str | None = None
    can_read_all_group_messages: bool = False


async def probe_token(token: str) -> TokenProbe:
    '''Проверяет токен через getMe. Токен в логи не выводится.'''
    bot = Bot(token=token, session=make_session())
    try:
        me = await bot.get_me()
    except TelegramUnauthorizedError:
        return TokenProbe(status='invalid')
    except Exception as exc:
        logger.warning('Не удалось проверить токен бота: %s', type(exc).__name__)
        return TokenProbe(status='unknown')
    finally:
        await bot.session.close()
    return TokenProbe(
        status='ok',
        user_id=me.id,
        username=me.username,
        can_read_all_group_messages=bool(me.can_read_all_group_messages),
    )


@dataclass(frozen=True)
class LinkReport:
    username: str | None
    level: str  # 'ok' | 'warn' | 'error'
    details: str


async def check_group_link(main_bot: Bot, token: str) -> LinkReport:
    '''Проверяет, что доп. бот состоит в группе и видит сообщения учеников.'''
    probe = await probe_token(token)
    if probe.status == 'invalid':
        return LinkReport(None, 'error', 'Telegram не принял токен')
    if probe.status == 'unknown':
        return LinkReport(None, 'error', 'не удалось связаться с Telegram')

    try:
        member = await main_bot.get_chat_member(config.GROUP_ID, probe.user_id)
    except TelegramAPIError:
        return LinkReport(probe.username, 'error', 'не найден в группе')

    if member.status not in MEMBER_STATUSES:
        return LinkReport(probe.username, 'error', 'не добавлен в группу')
    if member.status in ADMIN_STATUSES:
        return LinkReport(probe.username, 'ok', 'администратор группы, видит сообщения учеников')
    if probe.can_read_all_group_messages:
        return LinkReport(probe.username, 'ok', 'участник группы, режим приватности выключен')
    return LinkReport(
        probe.username,
        'warn',
        'участник без прав администратора: видит только команды и упоминания. '
        'Сделайте бота администратором',
    )

from aiogram.filters import BaseFilter
from aiogram.types import Message
from sqlalchemy import select

from core.config import config
from database.engine import async_session
from database.models import Student


class TeacherChatFilter(BaseFilter):
    async def __call__(self, message: Message) -> bool:
        return (
            message.chat.type == 'private'
            and message.from_user is not None
            and message.from_user.id in config.ADMIN_IDS
        )


class StudentTopicFilter(BaseFilter):
    async def __call__(self, message: Message):
        if message.chat.id != config.GROUP_ID or message.message_thread_id is None:
            return False
        async with async_session() as session:
            student = await session.scalar(
                select(Student).where(Student.topic_id == message.message_thread_id)
            )
        if student and student.tg_id == message.from_user.id:
            return {'student': student}
        return False

from sqlalchemy.ext.asyncio import create_async_engine, async_sessionmaker
from .models import Base
from core.config import config

engine = create_async_engine(
    config.DB_URL,
    echo=False,
    connect_args={"check_same_thread": False}
)

async_session = async_sessionmaker(engine, expire_on_commit=False)

MIGRATIONS = (
    ('chat_messages', 'session_id', 'INTEGER REFERENCES dialog_sessions(id)'),
    ('attempts', 'session_id', 'INTEGER REFERENCES dialog_sessions(id)'),
    ('dialog_sessions', 'report', 'TEXT'),
)
INDEXES = (
    'CREATE INDEX IF NOT EXISTS ix_chat_messages_session_id ON chat_messages (session_id)',
)


async def _migrate(conn) -> None:
    '''Добавляет недостающие nullable-колонки. Существующие данные не меняются.'''
    for table, column, ddl in MIGRATIONS:
        result = await conn.exec_driver_sql(f'PRAGMA table_info({table})')
        existing = {row[1] for row in result.fetchall()}
        if column not in existing:
            await conn.exec_driver_sql(f'ALTER TABLE {table} ADD COLUMN {column} {ddl}')
    for statement in INDEXES:
        await conn.exec_driver_sql(statement)


async def init_db():
    async with engine.begin() as conn:
        await conn.run_sync(Base.metadata.create_all)
        await _migrate(conn)

