def venv_works() -> bool:
    '''Проверяет, что python.exe из .venv реально запускается.'''
    py = venv_python()
    if not py.exists():
        return False
    try:
        subprocess.run(
            [str(py), '-c', 'import sys'],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=True,
            timeout=60,
        )
        return True
    except (OSError, subprocess.SubprocessError):
